namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public List<int> Ratings { get; set; } = [];

    public double AverageRating => Ratings.Count > 0 ? Ratings.Average() : 0;
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes =
    [
        new()
        {
            Id = 1, Title = "Bruschetta", Category = "appetizers",
            Ingredients = "Baguette\nTomatoes\nBasil\nGarlic\nOlive oil",
            Steps = "1. Slice and toast the baguette.\n2. Dice tomatoes and mix with chopped basil, garlic, and olive oil.\n3. Spoon mixture onto toast slices and serve."
        },
        new()
        {
            Id = 2, Title = "Spaghetti Carbonara", Category = "main-courses",
            Ingredients = "Spaghetti\nPancetta\nEggs\nParmesan cheese\nBlack pepper",
            Steps = "1. Cook spaghetti until al dente.\n2. Fry pancetta until crispy.\n3. Whisk eggs with grated Parmesan.\n4. Toss hot pasta with pancetta, then stir in egg mixture off heat.\n5. Season with black pepper."
        },
        new()
        {
            Id = 3, Title = "Chocolate Lava Cake", Category = "desserts",
            Ingredients = "Dark chocolate\nButter\nEggs\nSugar\nFlour",
            Steps = "1. Melt chocolate and butter together.\n2. Whisk eggs and sugar until fluffy.\n3. Fold in chocolate mixture and flour.\n4. Pour into greased ramekins.\n5. Bake at 220°C for 12 minutes."
        },
        new()
        {
            Id = 4, Title = "Tomato Basil Soup", Category = "soups",
            Ingredients = "Tomatoes\nOnion\nGarlic\nVegetable broth\nFresh basil\nCream",
            Steps = "1. Sauté onion and garlic.\n2. Add chopped tomatoes and broth.\n3. Simmer 20 minutes.\n4. Blend until smooth.\n5. Stir in cream and fresh basil."
        },
        new()
        {
            Id = 5, Title = "Mango Smoothie", Category = "beverages",
            Ingredients = "Mango\nYogurt\nHoney\nIce",
            Steps = "1. Peel and chop mango.\n2. Blend mango, yogurt, honey, and ice until smooth.\n3. Pour into a glass and serve."
        },
        new()
        {
            Id = 6, Title = "Banana Bread", Category = "baking",
            Ingredients = "Ripe bananas\nFlour\nSugar\nButter\nEggs\nBaking soda",
            Steps = "1. Mash bananas.\n2. Cream butter and sugar, add eggs.\n3. Mix in mashed bananas.\n4. Fold in flour and baking soda.\n5. Bake at 175°C for 60 minutes."
        }
    ];

    private int _nextId = 7;

    public IReadOnlyList<Recipe> GetAll() => _recipes;

    public IReadOnlyList<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _nextId++;
        _recipes.Add(recipe);
    }

    public void AddRating(int recipeId, int rating)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && rating is >= 1 and <= 5)
        {
            recipe.Ratings.Add(rating);
        }
    }
}

